/**
 * Commentary data model. One JSON file per source and book, generated by
 * `scripts/commentary/*` and committed under `content/commentary/<source>/<BOOK>.json`, so the site
 * builds without downloading anything.
 */

/** Bump on any breaking change to the committed commentary files. */
export const COMMENTARY_SCHEMA_VERSION = 1;

export type CommentarySourceId = 'stmark';

/** A run of commentary text. `reflection` marks the closing spiritual application (✦ in print). */
export interface CommentaryParagraph {
  readonly text: string;
  readonly kind?: 'reflection' | 'point';
}

/** Commentary on one verse or an inclusive range of verses. */
export interface CommentaryEntry {
  readonly verses: readonly [number, number];
  /** Page of the source PDF where the entry starts (1-based), for "read in the original". */
  readonly page: number;
  /** The section (e.g. "(1) التحية الرسولية") the entry belongs to, if any. */
  readonly section: string | null;
  readonly paragraphs: readonly CommentaryParagraph[];
}

export interface CommentaryChapter {
  readonly chapter: number;
  readonly page: number;
  /** Paragraphs before the first verse entry (chapter title, summary). */
  readonly intro: readonly CommentaryParagraph[];
  readonly entries: readonly CommentaryEntry[];
}

export interface CommentaryBook {
  readonly schemaVersion: typeof COMMENTARY_SCHEMA_VERSION;
  readonly source: CommentarySourceId;
  /** USFM book code (packages/bible). */
  readonly book: string;
  readonly language: 'ar';
  /** The source document(s), in order, with where each chapter range came from. */
  readonly documents: readonly { readonly url: string; readonly sha256: string; readonly chapters: readonly [number, number] }[];
  /**
   * How the text was obtained. `pdf-text-repaired`: the PDF's fonts reverse ligatures, and the
   * letter order was corrected automatically (logged in corrections.json); such books carry a notice. `pdf-link`: the PDF has
   * no extractable text, so the site links to it.
   */
  readonly extraction: 'pdf-text' | 'pdf-text-repaired' | 'pdf-link';
  readonly intro: readonly CommentaryParagraph[];
  readonly chapters: readonly CommentaryChapter[];
}

/** The entries whose verse range includes a verse. */
export function entriesForVerse(chapter: CommentaryChapter, verse: number): CommentaryEntry[] {
  return chapter.entries.filter(({ verses: [start, end] }) => verse >= start && verse <= end);
}
